package com.zenitrade.controller; import com.zenitrade.entity.Stock; import com.zenitrade.repository.StockRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/market") public class MarketController {private final StockRepository stocks;public MarketController(StockRepository s){stocks=s;} @GetMapping("/stocks") List<Stock> list(@RequestParam(defaultValue="") String q){return q.isBlank()?stocks.findAll():stocks.findBySymbolContainingIgnoreCaseOrCompanyNameContainingIgnoreCase(q,q);} @GetMapping("/stocks/{symbol}") Stock one(@PathVariable String symbol){return stocks.findBySymbolIgnoreCase(symbol).orElseThrow(()->new IllegalArgumentException("Stock not found"));} @GetMapping("/indices") List<Map<String,Object>> indices(){return List.of(idx("NIFTY 50",22683.75,-.42),idx("SENSEX",72529.07,-.33),idx("NIFTY BANK",54364.9,-.20),idx("NIFTY IT",34920.6,.58),idx("NIFTY FMCG",56100.4,.37),idx("NIFTY AUTO",27120.5,.64),idx("NIFTY PHARMA",21410.2,.41),idx("NIFTY METAL",10340.9,-.22),idx("NIFTY REALTY",9500.3,.75),idx("NIFTY MIDCAP 50",15820.7,.28));} private Map<String,Object> idx(String n,double p,double c){return Map.of("name",n,"price",p,"changePercent",c);} }
